create extension if not exists vector with schema extensions;

create table if not exists public.vow_knowledge (
  id uuid primary key default gen_random_uuid(),
  domain text not null,
  topic text not null,
  title text not null,
  content text not null,
  principles jsonb not null default '[]'::jsonb,
  recommended_actions jsonb not null default '[]'::jsonb,
  metrics jsonb not null default '[]'::jsonb,
  cautions jsonb not null default '[]'::jsonb,
  source_url text,
  active boolean not null default true,
  search_vector tsvector generated always as (
    setweight(to_tsvector('english', coalesce(domain, '')), 'A') ||
    setweight(to_tsvector('english', coalesce(topic, '')), 'A') ||
    setweight(to_tsvector('english', coalesce(title, '')), 'B') ||
    setweight(to_tsvector('english', coalesce(content, '')), 'C')
  ) stored,
  embedding extensions.vector(384),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint vow_knowledge_domain_topic_title_key unique (domain, topic, title)
);

create index if not exists vow_knowledge_search_idx on public.vow_knowledge using gin (search_vector);
create index if not exists vow_knowledge_domain_idx on public.vow_knowledge (domain, active);
create index if not exists vow_knowledge_embedding_idx on public.vow_knowledge using hnsw (embedding vector_cosine_ops);

alter table public.vow_knowledge enable row level security;

create or replace function public.match_vow_knowledge(
  query_text text,
  domain_filter text default null,
  match_count integer default 8
)
returns table (
  id uuid, domain text, topic text, title text, content text,
  principles jsonb, recommended_actions jsonb, metrics jsonb, cautions jsonb,
  source_url text, score real
)
language sql stable
as $$
  with q as (select websearch_to_tsquery('english', coalesce(query_text, '')) as tsq)
  select k.id, k.domain, k.topic, k.title, k.content, k.principles,
         k.recommended_actions, k.metrics, k.cautions, k.source_url,
         ts_rank_cd(k.search_vector, q.tsq)::real as score
  from public.vow_knowledge k, q
  where k.active
    and (domain_filter is null or k.domain = domain_filter)
    and k.search_vector @@ q.tsq
  order by ts_rank_cd(k.search_vector, q.tsq) desc, k.updated_at desc
  limit greatest(1, least(coalesce(match_count, 8), 20));
$$;

insert into public.vow_knowledge (domain, topic, title, content, principles, recommended_actions, metrics, cautions) values
('fitness','running','Build running capacity gradually','Progress running volume and intensity gradually. Most training should be comfortable enough to support consistency, with harder sessions separated by recovery.','["Consistency beats occasional maximal sessions","Increase workload gradually","Use recovery as part of training"]','["Set a realistic weekly running frequency","Keep most runs easy","Add one focused quality session when appropriate","Review progress weekly"]','["weekly distance","easy-run duration","comfortable pace","perceived effort"]','["Do not treat pain as a target","Avoid sudden large jumps in training load"]'),
('fitness','strength','Progressive strength training','Strength improves when training provides a manageable challenge and the person recovers between sessions. Progress can come from repetitions, load, range of motion, technique or control.','["Prioritise technique","Progress one variable at a time","Recovery supports adaptation"]','["Choose a small set of movement patterns","Track sets and repetitions","Progress gradually when technique is stable"]','["sets","repetitions","load","range of motion","session consistency"]','["Do not chase maximal loads unnecessarily","Stop or modify an exercise if technique breaks down"]'),
('fitness','cycling','Cycling endurance','Endurance cycling is developed through consistent aerobic work, appropriate pacing and gradual increases in duration.','["Build duration before repeatedly chasing speed","Use varied intensity","Maintain recovery days"]','["Set a weekly riding target","Use mostly sustainable efforts","Track duration and distance"]','["ride duration","distance","average effort","weekly frequency"]','["Account for traffic, weather and road safety"]'),
('fitness','football','Football performance','Football combines technical skill, repeated running, acceleration, decision-making and recovery. Training should combine sport-specific practice with general physical preparation.','["Specific practice matters","Quality and recovery both matter","Train the demands of the position"]','["Include ball work","Use short high-quality movement drills","Review match performance","Balance football with other training"]','["minutes played","technical actions","training attendance","perceived effort"]','["Avoid stacking multiple hard sessions without recovery"]'),
('education','study','Active learning','Learning improves when the learner retrieves information, practises application and receives feedback instead of only rereading notes.','["Retrieve before reviewing","Practise the task you will be assessed on","Use mistakes as feedback"]','["Use practice questions","Explain concepts from memory","Mark work against reliable answers","Keep an error log"]','["questions completed","accuracy","recall success","error categories"]','["Do not measure studying only by hours spent"]'),
('education','exams','Exam preparation','Effective exam preparation combines syllabus coverage, retrieval practice, timed practice and targeted correction of weak areas.','["Diagnose before drilling","Practise under realistic conditions","Revisit recurring errors"]','["Map topics to confidence","Complete timed sections","Review every mistake","Repeat weak question types"]','["topic accuracy","timed score","error rate","coverage percentage"]','["Avoid spending all study time on topics already mastered"]'),
('education','mathematics','Mathematics problem solving','Mathematics improves through deliberate practice of varied problems, clear working and correction of misconceptions.','["Understand methods, not just answers","Mix familiar and unfamiliar problems","Write enough working to diagnose errors"]','["Practise without notes first","Categorise mistakes","Redo missed problems later"]','["accuracy","time per problem","mistake type","retention after delay"]','["Avoid memorising procedures without understanding when they apply"]'),
('education','languages','Language learning','Language ability grows through repeated exposure, retrieval, listening, reading, speaking and writing. Frequent shorter sessions are often easier to sustain than rare long sessions.','["Use the language actively","Space repetition over time","Connect vocabulary to context"]','["Review high-value vocabulary","Practise short writing and speaking","Use listening regularly","Track recurring mistakes"]','["words retained","comprehension accuracy","speaking practice minutes","writing corrections"]','["Do not rely exclusively on isolated vocabulary lists"]'),
('career','job_search','Career preparation','Career progress is built through evidence of skills, targeted applications, communication and consistent relationship building.','["Show evidence, not only claims","Tailor applications to the opportunity","Build relationships before you need them"]','["Create a skills inventory","Build a small portfolio","Tailor CVs and messages","Track applications and follow-ups"]','["applications sent","response rate","portfolio projects","conversations started"]','["Protect personal information when networking online"]'),
('career','interviews','Interview preparation','Interview performance improves through understanding the role, preparing concise examples and practising answers aloud.','["Prepare evidence-based examples","Understand the organisation","Practise clarity rather than memorised scripts"]','["Research the role","Prepare situation-action-result examples","Practise common questions","Prepare thoughtful questions"]','["practice sessions","answer clarity","examples prepared","questions prepared"]','["Do not invent experience or qualifications"]'),
('technology','programming','Learning programming','Programming is learned effectively by combining concepts with frequent small projects, debugging and reading existing code.','["Build while learning","Debug systematically","Read code as well as writing it"]','["Choose a small project","Break tasks into functions","Keep a bug log","Refactor after working"]','["features completed","bugs resolved","projects shipped","concepts demonstrated"]','["Avoid copying code without understanding its behaviour"]'),
('technology','web_development','Building web applications','Good web development combines user needs, simple architecture, accessible interfaces, reliable data handling and iterative testing.','["Solve a real user problem","Keep architecture understandable","Test critical flows"]','["Define user journeys","Build the smallest useful version","Test authentication and data flows","Monitor errors"]','["critical flows passing","error rate","load time","user task completion"]','["Never expose server secrets in client code"]'),
('technology','product','Product development','Products improve through clear problem definition, fast feedback and disciplined prioritisation.','["Start with the user problem","Prioritise outcomes","Ship small improvements and learn"]','["Write a problem statement","Define success metrics","Prototype","Collect feedback","Prioritise the next experiment"]','["activation","retention","task completion","feedback themes"]','["Do not add features simply because they are technically interesting"]'),
('productivity','habits','Habit formation','Habits become easier when the desired behaviour has a clear cue, low friction and a realistic starting point.','["Reduce friction","Start small","Attach behaviour to a stable cue"]','["Define one observable behaviour","Choose a cue","Prepare the environment","Track consistency"]','["days completed","weekly consistency","friction points"]','["Avoid treating one missed day as failure"]'),
('productivity','time_management','Time management','Effective time management comes from choosing priorities, estimating work realistically and protecting focused time.','["Prioritise outcomes","Leave capacity for uncertainty","Schedule important work"]','["Choose three priorities","Break work into next actions","Use focused blocks","Review the plan daily"]','["priority completion","planned vs actual time","unfinished carryover"]','["Avoid filling every minute of the day"]'),
('productivity','focus','Deep work','Focused work improves when distractions are reduced and the task has a clearly defined next action.','["Define the outcome before starting","Remove avoidable distractions","Work in sustainable blocks"]','["Write the next action","Silence nonessential notifications","Use a timer","Take planned breaks"]','["focused minutes","tasks completed","interruption count"]','["Do not confuse long sessions with effective work"]'),
('finance','budgeting','Personal budgeting','A useful budget gives money clear jobs while leaving room for irregular expenses and changing priorities.','["Track reality before optimising it","Separate needs from wants","Keep a buffer"]','["Record income and spending","Group expenses","Set savings targets","Review monthly"]','["savings rate","essential spending","planned vs actual"]','["Financial decisions depend on individual circumstances"]'),
('finance','saving','Saving systems','Saving is easier when a specific purpose, amount and routine are defined in advance.','["Automate where possible","Use specific goals","Protect emergency reserves"]','["Name the goal","Set a target","Choose a regular contribution","Review progress"]','["amount saved","contribution consistency","goal progress"]','["Do not sacrifice essential needs for an arbitrary target"]'),
('personal_development','goals','Goal setting','Strong goals define an observable outcome, a timeframe, a baseline and the actions that can influence the outcome.','["Make the outcome measurable","Define a realistic timeframe","Separate controllable actions from outcomes"]','["Write the desired outcome","Record the baseline","Choose leading actions","Set checkpoints"]','["outcome metric","action consistency","checkpoint progress"]','["Avoid choosing metrics that cannot actually be measured"]'),
('personal_development','reflection','Weekly review','Regular reflection helps identify what worked, what failed and what should change next.','["Review evidence, not feelings alone","Keep what works","Change one important thing at a time"]','["Review wins","Review misses","Identify bottlenecks","Choose next week priorities"]','["completion rate","bottlenecks resolved","weekly priorities completed"]','["Reflection should lead to an actionable change"]'),
('creative','writing','Writing practice','Writing improves through producing drafts, getting feedback, revising and studying strong examples.','["Draft before polishing","Revise for clarity","Read actively"]','["Write regularly","Use a clear purpose","Revise structure before wording","Keep a feedback log"]','["words drafted","pieces completed","revision passes","feedback items resolved"]','["Do not optimise every sentence before the structure works"]'),
('creative','design','Design practice','Design improves through solving a defined problem, exploring alternatives and testing with users.','["Design for a user need","Explore alternatives","Test assumptions"]','["Define the user","Sketch multiple solutions","Prototype","Test and revise"]','["iterations","usability issues","task success","feedback themes"]','["Avoid prioritising aesthetics over usability"]'),
('travel','planning','Travel planning','Reliable travel planning combines dates, transport, accommodation, documents, budget, contingencies and local constraints.','["Confirm hard constraints first","Keep copies of essential information","Plan contingencies"]','["Set dates","Confirm transport","Set a budget","Check entry requirements","Prepare a contingency plan"]','["budget variance","tasks completed","documents confirmed"]','["Entry requirements and local rules should be checked with official sources"]'),
('life_admin','organisation','Personal organisation','Organisation works when information has a trusted home and tasks have clear next actions.','["Use one trusted task system","Capture commitments quickly","Review regularly"]','["Create categories","Write next actions","Set reminders","Do a weekly reset"]','["overdue tasks","capture-to-completion time","weekly review completion"]','["Avoid maintaining multiple conflicting task lists"]'),
('communication','teamwork','Team communication','Teams work better when responsibilities, decisions and expectations are explicit.','["Clarify ownership","Record decisions","Raise blockers early"]','["Define roles","Write decisions down","Set check-ins","Escalate blockers constructively"]','["tasks completed","blocker age","decision turnaround"]','["Do not assume silence means agreement"]'),
('communication','public_speaking','Public speaking','Speaking improves through preparation, rehearsal, clear structure and gradual exposure to real audiences.','["Know the core message","Practise aloud","Use a simple structure"]','["Write the key message","Rehearse","Time the delivery","Practise with a small audience"]','["rehearsals","delivery time","audience feedback"]','["Avoid memorising every word if it makes delivery rigid"]'),
('learning','research','Research skills','Good research starts with a precise question, uses appropriate sources and records evidence so claims can be checked.','["Define the question","Prefer authoritative sources","Separate evidence from interpretation"]','["Write the research question","Collect primary or authoritative sources","Record claims and evidence","Cross-check important facts"]','["sources checked","claims supported","contradictions resolved"]','["Be cautious with unsourced claims and outdated information"]'),
('learning','critical_thinking','Critical thinking','Critical thinking involves identifying assumptions, checking evidence, considering alternatives and distinguishing correlation from causation.','["Ask what would change your mind","Check the evidence","Consider alternative explanations"]','["State the claim","List assumptions","Find supporting and opposing evidence","Test the strongest alternative"]','["assumptions identified","sources checked","alternative explanations considered"]','["Confidence should match evidence quality"]'),
('wellbeing','sleep','Sleep routine','A consistent sleep schedule and a suitable sleep environment can support concentration, learning and recovery.','["Keep a reasonably consistent schedule","Protect enough time for sleep","Make the environment comfortable"]','["Set a consistent bedtime window","Create a wind-down routine","Reduce avoidable late distractions"]','["sleep consistency","morning alertness","daytime concentration"]','["Persistent sleep problems should be discussed with a qualified professional"]'),
('wellbeing','stress','Stress management','Managing stress is easier when demands are identified, controllable actions are separated from uncontrollable factors and recovery is protected.','["Identify the actual stressor","Take one controllable action","Protect recovery"]','["Write down concerns","Choose the next action","Use breaks and social support","Review recurring causes"]','["stress rating","recovery activities","tasks resolved"]','["Severe or persistent distress warrants support from a trusted adult or qualified professional"]')
on conflict (domain, topic, title) do update set content=excluded.content, principles=excluded.principles, recommended_actions=excluded.recommended_actions, metrics=excluded.metrics, cautions=excluded.cautions, active=true, updated_at=now();
